/**
 * The text of the Terms and Conditions page (Affiliate Program Agreement): part of the default dictionary as
 * `terms.sections`. Taken word for word from the client's PDF "terms-and-conditions.pdf" (52 pages, October 2026):
 * paragraphs, sub-items and bold follow the PDF (the defined terms as a list, numbered sub-items such as 6.3.1 and
 * 4.1.5.1 as items, the paragraphs that follow a sub-item at the left margin as paragraphs, cross-references in
 * running text not bold); e-mail and web addresses are links.
 *
 * Inline markup in every string: **bold** (SemiBold) and [text](href) (a link).
 * Blocks: a string = a paragraph · { strong } = a bold paragraph in Text Primary · { terms } = a list of defined
 * terms (no markers) · { clauses } = a list of numbered sub-clauses (• marker) · { table } = a table (the Privacy
 * Policy page): the caption (screen readers only), the column titles, the rows (the first cell titles the row).
 * `toc: true` = an entry of the table of contents; the sections after it (the DPA parts, the annexes) belong to it.
 */
export interface TermsTable {
  caption: string;
  head: string[];
  rows: string[][];
}

export type TermsBlock = string | { strong: string } | { terms: string[] } | { clauses: string[] } | { table: TermsTable };

export interface TermsSection {
  id: string;
  level: 2 | 3;
  toc: boolean;
  title: string;
  blocks: TermsBlock[];
}

